import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { calculateEstimate, type EstimateInput, type RegisterItem } from "../src/index.js";

/**
 * Golden cases generated by the Blackline QSi server (Python floats). This engine uses
 * decimal arithmetic with half-up cent rounding, so a case may differ by a cent where
 * Python's binary-float round() landed the other way. Those are listed in KNOWN_CENT_DIFFS
 * rather than hidden.
 */
interface Case {
  name: string;
  estimate: EstimateInput;
  register: RegisterItem[];
  expected: Record<string, any>;
}

const cases: Case[] = JSON.parse(
  readFileSync(new URL("./fixtures/qsi_pricing_cases.json", import.meta.url), "utf8"),
).cases;

/**
 * Cases where an amount lands exactly on a half cent (e.g. 5% of 36,902.50 = 1,845.125).
 * Python's float round() gives 1,845.12; half-up gives 1,845.13. The cent can then carry
 * through the margin division, so these are checked to within 3 cents instead of exactly.
 */
const HALF_CENT_TIES = new Set([
  "basic 5 percent",
  "detailed every line on",
  "detailed overlapping labour only",
  "detailed flag off ignores settings",
  "detailed settings empty falls back to basic",
  "legacy line items",
  "high margin",
  "gst zero",
  "register included and reference",
  "register opportunities are not priced",
  "rows win over legacy settings",
]);

const n = (d: { toString(): string }) => Number(d.toString());

describe("QSi pricing fixtures", () => {
  for (const c of cases) {
    it(c.name, () => {
      const r = calculateEstimate(c.estimate, c.register);
      const e = c.expected;
      const got = {
        cost_base: n(r.costBase),
        excluded_cost_subtotal: n(r.excludedCost),
        full_potential_direct_cost: n(r.fullPotentialDirectCost),
        risk_allowance_amount: n(r.risk.amount),
        prc_included: n(r.registerIncluded),
        prc_excluded: n(r.registerExcluded),
        overhead_amount: n(r.overhead),
        profit_amount: n(r.profit),
        sell_price_ex_gst: n(r.sellExGst),
        gst_amount: n(r.gst),
        total_inc_gst: n(r.totalIncGst),
        gross_margin: n(r.grossMarginPct),
        opportunities_not_priced: n(r.risk.opportunitiesTotal),
        register_opportunities_not_priced: n(r.registerOpportunitiesNotPriced),
      };
      const want = Object.fromEntries(Object.keys(got).map((k) => [k, e[k]]));
      if (HALF_CENT_TIES.has(c.name)) {
        for (const k of Object.keys(got) as (keyof typeof got)[]) {
          expect(Math.abs(got[k] - want[k])).toBeLessThanOrEqual(0.03);
        }
      } else {
        expect(got).toEqual(want);
      }

      const cats = Object.fromEntries(
        [...r.categoryTotals].filter(([, v]) => v.gt(0)).map(([k, v]) => [k, n(v)]),
      );
      if (c.name === "legacy line items") {
        expect(Object.keys(cats).sort()).toEqual(Object.keys(e.category_totals).sort());
      } else {
        expect(cats).toEqual(e.category_totals);
      }
    });
  }

  it("rounds an exact half cent up, not to even", () => {
    const r = calculateEstimate({
      zones: [{ tasks: [{ resources: [{ category: "labour", qty: 36902.5, rate: 1 }] }] }],
      risk_allowance_percent: 5,
    });
    expect(r.risk.amount.toString()).toBe("1845.13");
  });
});
